<script setup lang="ts">
import { ref, computed } from 'vue'
import { useVoiceStore } from '@stores/useVoiceStore'
import type { Channel } from '../types'

const voiceStore = useVoiceStore()

const channels = ref<Channel[]>([])
const newChannelName = ref('')
const showCreateModal = ref(false)
const isCreating = ref(false)
const createError = ref<string | null>(null)

const currentChannelId = computed(() => voiceStore.state.currentChannel)

function selectChannel(channelId: string) {
  voiceStore.joinChannel(channelId)
}

async function createChannel() {
  if (!newChannelName.value.trim()) return
  
  createError.value = null
  isCreating.value = true
  
  try {
    await voiceStore.createChannel({
      name: newChannelName.value.trim(),
      position: { x: 0, y: 0, z: 0 },
      isPrivate: false,
    })
    newChannelName.value = ''
    showCreateModal.value = false
  } catch (err) {
    createError.value = err instanceof Error ? err.message : 'Fehler beim Erstellen'
  } finally {
    isCreating.value = false
  }
}

function deleteChannel(channelId: string) {
  if (confirm('Diesen Kanal wirklich löschen?')) {
    voiceStore.deleteChannel(channelId)
  }
}
</script>

<template>
  <div class="channel-list">
    <div class="channel-header">
      <h3>Kanäle</h3>
      <button @click="showCreateModal = true" class="btn btn-icon btn-sm" aria-label="Neuen Kanal erstellen">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <line x1="12" y1="5" x2="12" y2="19" />
          <line x1="5" y1="12" x2="19" y2="12" />
        </svg>
      </button>
    </div>
    
    <ul class="channels" role="listbox" aria-label="Verfügbare Kanäle">
      <li v-for="channel in channels" :key="channel.id" class="channel-item">
        <button
          @click="selectChannel(channel.id)"
          class="channel-btn"
          :class="{ active: currentChannelId === channel.id }"
          :aria-selected="currentChannelId === channel.id"
          role="option"
        >
          <span class="channel-icon">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <path d="M12 19l7-7 3 3-7 7-3-3z" />
              <path d="M18 13l-7-7-3 3 7 7 3-3z" />
            </svg>
          </span>
          <span class="channel-name">{{ channel.name }}</span>
          <span v-if="channel.isPrivate" class="private-badge" title="Privat">
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <rect x="3" y="11" width="18" height="11" rx="2" ry="2" />
              <path d="M7 11V7a5 5 0 0 1 10 0v4" />
            </svg>
          </span>
        </button>
        <button
          v-if="currentChannelId !== channel.id"
          @click.stop="deleteChannel(channel.id)"
          class="btn btn-icon btn-xs btn-danger"
          aria-label="Kanal löschen"
        >
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <polyline points="3 6 5 6 21 6" />
            <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" />
          </svg>
        </button>
      </li>
      
      <li v-if="channels.length === 0" class="empty-state">
        <p>Keine Kanäle verfügbar</p>
        <button @click="showCreateModal = true" class="btn btn-primary btn-sm">
          Ersten Kanal erstellen
        </button>
      </li>
    </ul>
    
    <div v-if="showCreateModal" class="modal-overlay" @click.self="showCreateModal = false">
      <div class="modal" role="dialog" aria-modal="true" aria-labelledby="create-channel-title">
        <h3 id="create-channel-title">Neuen Kanal erstellen</h3>
        <div v-if="createError" class="error">{{ createError }}</div>
        <div class="form-group">
          <label for="channelName">Kanalname</label>
          <input
            id="channelName"
            v-model="newChannelName"
            type="text"
            @keyup.enter="createChannel"
            placeholder="z. B. General, Gaming, Meeting"
            autofocus
          />
        </div>
        <div class="modal-actions">
          <button @click="showCreateModal = false" class="btn btn-secondary">Abbrechen</button>
          <button @click="createChannel" class="btn btn-primary" :disabled="isCreating || !newChannelName.trim()">
            {{ isCreating ? 'Erstelle...' : 'Erstellen' }}
          </button>
        </div>
      </div>
    </div>
  </div>
</template>

