<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted } from 'vue'
import { useRouter } from 'vue-router'
import { useAuthStore } from '@stores/useAuthStore'
import { useVoiceStore } from '@stores/useVoiceStore'
import { useHead } from '@vueuse/head'
import ChannelList from '@components/ChannelList.vue'
import PeerList from '@components/PeerList.vue'
import VoiceControls from '@components/VoiceControls.vue'
import AudioVisualizer from '@components/AudioVisualizer.vue'

const router = useRouter()
const authStore = useAuthStore()
const voiceStore = useVoiceStore()

useHead({
  title: 'Sprachchat - SimpleVoiceChat',
})

const showChannels = ref(true)
const showPeers = ref(true)
const showVisualizer = ref(false)

const isConnected = computed(() => voiceStore.state.isConnected)
const isConnecting = computed(() => voiceStore.state.isConnecting)
const currentChannel = computed(() => voiceStore.state.currentChannel)
const peerCount = computed(() => voiceStore.peerCount)
const microphoneWarning = computed(() => voiceStore.state.microphoneWarning)

async function handleDisconnect() {
  await voiceStore.disconnect()
}

async function handleLeaveChannel() {
  await voiceStore.leaveChannel()
}

onMounted(() => {
  if (!authStore.isAuthenticated) {
    router.push('/login')
    return
  }
  voiceStore.restoreSettings()
})

onUnmounted(() => {
  voiceStore.persistSettings()
})
</script>

<template>
  <div class="voice-view">
    <header class="voice-header">
      <div class="header-left">
        <h1>SimpleVoiceChat</h1>
        <span v-if="currentChannel" class="channel-badge">{{ currentChannel }}</span>
      </div>
      
      <div class="header-center">
        <div class="connection-status" :class="['status', { connected: isConnected, connecting: isConnecting }]">
          <span class="status-dot" aria-hidden="true"></span>
          <span>{{ isConnecting ? 'Verbinde...' : isConnected ? 'Verbunden' : 'Getrennt' }}</span>
        </div>
        
        <div v-if="isConnected" class="peer-count">
          <span>{{ peerCount }} {{ peerCount === 1 ? 'Teilnehmer' : 'Teilnehmer' }}</span>
        </div>
      </div>
      
      <div class="header-right">
        <button 
          v-if="isConnected"
          @click="handleLeaveChannel"
          class="btn btn-secondary"
          aria-label="Kanal verlassen"
        >
          Kanal verlassen
        </button>
        <button 
          v-else-if="isConnecting"
          @click="handleDisconnect"
          class="btn btn-secondary"
          aria-label="Verbindung abbrechen"
        >
          Abbrechen
        </button>
        <button @click="$router.push('/settings')" class="btn btn-icon" aria-label="Einstellungen">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <circle cx="12" cy="12" r="3" />
            <path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z" />
          </svg>
        </button>
        <button 
          v-if="isConnected"
          @click="handleDisconnect"
          class="btn btn-danger"
          aria-label="Trennen"
        >
          Trennen
        </button>
      </div>
    </header>
    
    <main class="voice-main">
      <div v-if="microphoneWarning" class="microphone-warning" role="status">
        {{ microphoneWarning }}
      </div>
      <aside v-show="showChannels" class="sidebar sidebar-channels">
        <ChannelList @channel-selected="handleLeaveChannel" />
      </aside>
      
      <section class="voice-content">
        <div class="voice-controls-section">
          <VoiceControls />
        </div>
        
        <div class="visualizer-section">
          <AudioVisualizer v-show="showVisualizer" />
        </div>
        
        <aside v-show="showPeers" class="sidebar sidebar-peers">
          <PeerList />
        </aside>
      </section>
    </main>
    
    <footer class="voice-footer">
      <div class="footer-toggle">
        <button @click="showChannels = !showChannels" class="toggle-btn" :class="{ active: showChannels }" aria-label="Kanäle anzeigen">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
